import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT_DIR = path.join(__dirname, '..');

const ELECTION_CONFIG = JSON.parse(
  fs.readFileSync(path.join(ROOT_DIR, 'config', 'election.json'), 'utf8')
);

const OUTPUT_FILE = path.join(ROOT_DIR, 'src', 'scss', '_colors-auto.scss');

function generateScss() {
  const lines = [
    '// AUTO-GENERATED by scripts/generate-scss-colors.js',
    '// Do not edit manually. Source of truth: config/election.json',
    '',
  ];

  const seenKeys = new Set();
  const entries = [];

  // All party groups (lista, sup, ct) — sup-only and CT lists included
  for (const group of ['lista', 'sup', 'ct']) {
    for (const party of (ELECTION_CONFIG.parties[group] || [])) {
      if (!seenKeys.has(party.key)) {
        entries.push({ key: party.key, color: party.color, name: party.displayName });
        seenKeys.add(party.key);
      }
    }
  }

  for (const project of ELECTION_CONFIG.projects) {
    if (!seenKeys.has(project.key)) {
      entries.push({ key: project.key, color: project.color, name: project.displayName });
      seenKeys.add(project.key);
    }
  }

  for (const e of entries) {
    const varName = `$color-${e.key}`;
    lines.push(`${varName}: ${e.color};`);
  }

  lines.push('');

  // Generate .bar-* classes for all parties and projects
  for (const e of entries) {
    lines.push(`.bar-${e.key} { background-color: $color-${e.key}; }`);
  }

  lines.push('');

  // Generate .vote-* and .terri-mov color maps for @each loops
  lines.push('// Map for @each loops: $key: $color-variable');
  lines.push('$party-colors: (');
  for (const e of entries) {
    lines.push(`  ${e.key}: $color-${e.key},`);
  }
  lines.push(');');
  lines.push('');

  // Text color for each party's pill, picked from the background's
  // luminance (WCAG): dark text on light colors (lime, pink, gold, orange),
  // white on dark ones. Used in both themes, so a new list never needs a
  // hand-made exception.
  const lum = (hex) => {
    let h = hex.replace('#', '');
    if (h.length === 3) h = h.split('').map((c) => c + c).join('');
    const [r, g, b] = [0, 2, 4].map((i) => {
      const v = parseInt(h.slice(i, i + 2), 16) / 255;
      return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
    });
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  };
  lines.push('$party-ink: (');
  for (const e of entries) {
    lines.push(`  ${e.key}: ${lum(e.color) > 0.179 ? '#111111' : '#ffffff'},`);
  }
  lines.push(');');

  fs.writeFileSync(OUTPUT_FILE, lines.join('\n') + '\n');
  console.log(`Generated ${OUTPUT_FILE} with ${entries.length} color entries`);
}

generateScss();